sys_ui_page.client_script:
var evResolverSaving = false;
var evTemplates = [];
var evResolverDialog;
var evResolverRecordId;

function evMostrarErro(message) {
    var element = gel('ev_error');

    element.textContent = message || '';
    element.style.display = message ? 'block' : 'none';
}

function evLerResposta(answer) {
    var response;

    try {
        response = JSON.parse(answer || '{}');
    } catch (error) {
        response = { error: 'Resposta inválida do servidor.' };
    }

    if (!response || response.success !== true) {
        evMostrarErro(
            (response && response.error) ||
            'Não foi possível executar a ação.'
        );
        return null;
    }

    return response;
}

function evCarregarOpcoes() {
    evResolverDialog = GlideDialogWindow.get();
    evResolverRecordId = evResolverDialog.getPreference('sysparm_record_id');

    var ga = new GlideAjax('x_fub_fundbrad_ev.EvResolverAjax');

    ga.addParam('sysparm_name', 'opcoes');
    ga.addParam('sysparm_record_id', evResolverRecordId);

    ga.getXMLAnswer(function (answer) {
        var response = evLerResposta(answer);
        if (!response) return;

        var select = gel('ev_resolution_code');
        var options = response.resolutionCodes || [];

        select.options.length = 0;
        select.add(new Option('-- Selecione --', ''));

        options.forEach(function (option) {
            select.add(new Option(
                option.displayValue || option.label,
                option.value
            ));
        });

        if (!options.length) {
            evMostrarErro('Nenhum código de resolução disponível.');
            return;
        }

        evCarregarTemplates();
    });
}

function evCarregarTemplates() {
    var ga = new GlideAjax('x_fub_fundbrad_ev.EvResolverAjax');

    ga.addParam('sysparm_name', 'templates');
    ga.addParam('sysparm_record_id', evResolverRecordId);

    ga.getXMLAnswer(function (answer) {
        var response = evLerResposta(answer);
        if (!response) return;

        evTemplates = response.templates || [];

        var select = gel('ev_template');

        select.options.length = 0;
        select.add(new Option(
            evTemplates.length
                ? '-- Selecione --'
                : 'Nenhum template disponível',
            ''
        ));

        evTemplates.forEach(function (template) {
            select.add(new Option(
                template.displayValue,
                template.value
            ));
        });

        select.disabled = !evTemplates.length;

        if (evTemplates.length === 1) {
            select.value = evTemplates[0].value;
            evAplicarTemplate();
        }

        gel('ev_confirm').disabled = false;
    });
}

function evAplicarTemplate() {
    if (evResolverSaving) return;

    var id = gel('ev_template').value;
    var text = '';

    for (var i = 0; i < evTemplates.length; i++) {
        if (evTemplates[i].value === id) {
            text = evTemplates[i].text || '';
            break;
        }
    }

    gel('ev_close_notes').value = text;
    evMostrarErro('');
}

function evConfirmar() {
    if (evResolverSaving) return false;

    evMostrarErro('');

    var code = gel('ev_resolution_code').value;
    var notes = gel('ev_close_notes').value.trim();

    if (!code || notes.length < 20) {
        evMostrarErro(
            'Selecione o código e informe pelo menos 20 caracteres nas anotações.'
        );
        return false;
    }

    evResolverSaving = true;
    gel('ev_confirm').disabled = true;
    gel('ev_resolution_code').disabled = true;
    gel('ev_template').disabled = true;
    gel('ev_close_notes').disabled = true;

    var ga = new GlideAjax('x_fub_fundbrad_ev.EvResolverAjax');

    ga.addParam('sysparm_name', 'resolver');
    ga.addParam('sysparm_record_id', evResolverRecordId);
    ga.addParam('sysparm_resolution_code', code);
    ga.addParam('sysparm_template', gel('ev_template').value);
    ga.addParam('sysparm_close_notes', notes);

    ga.getXMLAnswer(function (answer) {
        if (!evLerResposta(answer)) {
            evResolverSaving = false;
            gel('ev_confirm').disabled = false;
            gel('ev_resolution_code').disabled = false;
            gel('ev_template').disabled = !evTemplates.length;
            gel('ev_close_notes').disabled = false;
            return;
        }

        evResolverDialog.destroy();
        window.top.location.reload();
    });

    return false;
}

function evCancelar() {
    if (evResolverSaving) return false;

    evResolverDialog.destroy();
    return false;
}

addLoadEvent(evCarregarOpcoes);
